export function deepMerge(base, patch) {
    const out = { ...base };
    for (const [key, value] of Object.entries(patch)) {
        const existing = out[key];
        if (value &&
            typeof value === "object" &&
            !Array.isArray(value) &&
            existing &&
            typeof existing === "object" &&
            !Array.isArray(existing)) {
            out[key] = deepMerge(existing, value);
        }
        else {
            out[key] = value;
        }
    }
