 */
export async function checkConnectivity(apiKey, proxyUrl = getProxyUrl()) {
    if (!validateApiKey(apiKey)) {
        return {
            ok: false,
            status: "invalid_key",
            message: `Invalid API key format. Get a key at ${DASHBOARD_URL}`,
        };
    }
