const KEY = "duel_abcd1234_" + "a".repeat(32);
const KEY2 = "duel_AB12cd34_" + "Z9".repeat(16);

describe("constants", () => {
  test("urls", () => {
    assert.equal(DEFAULT_PROXY_URL, "https://duelagents.com/v1");
    assert.equal(DASHBOARD_URL, "https://duelagents.com/dashboard/settings");
    assert.equal(KEY_DOCS_URL, "https://duelagents.com/dashboard/settings");
