  test("rejects empty / nullish", () => {
    assert.equal(validateApiKey(""), false);
    assert.equal(validateApiKey(undefined), false);
    assert.equal(validateApiKey(null), false);
  });
  test("rejects wrong prefix, lengths and charset", () => {
    assert.equal(validateApiKey("sk_abcd1234_" + "a".repeat(32)), false);
    assert.equal(validateApiKey("duel_abcd123_" + "a".repeat(32)), false);
    assert.equal(validateApiKey("duel_abcd12345_" + "a".repeat(32)), false);
    assert.equal(validateApiKey("duel_abcd1234_" + "a".repeat(31)), false);
    assert.equal(validateApiKey("duel_abcd1234_" + "a".repeat(33)), false);
    assert.equal(validateApiKey("duel_abcd-234_" + "a".repeat(32)), false);
    assert.equal(validateApiKey("duel_abcd1234_" + "a".repeat(31) + "-"), false);
    assert.equal(validateApiKey(KEY + "\nduel"), false);
  });
  test("rejects non-strings", () => {
    assert.equal(validateApiKey(123 as unknown as string), false);
  });
});

describe("requireApiKey", () => {
  test("returns the trimmed key", () => {
    assert.equal(requireApiKey(`  ${KEY} `), KEY);
  });
  test("throws with default label and dashboard url", () => {
    assert.throws(
      () => requireApiKey("nope"),
      (err: Error) => {
        assert.match(err.message, /Invalid or missing DUEL_API_KEY\./);
        assert.ok(err.message.includes(DASHBOARD_URL));
        assert.match(err.message, /duel_<prefix>_<secret>/);
        return true;
      },
    );
  });
  test("throws with a custom label", () => {
    assert.throws(() => requireApiKey(undefined, "--key"), /Invalid or missing --key\./);
    assert.throws(() => requireApiKey(null, "--key"), /--key/);
    assert.throws(() => requireApiKey("", "--key"), /--key/);
  });
