describe("getProxyUrl", () => {
  const saved = {
    DUEL_PROXY_URL: process.env.DUEL_PROXY_URL,
    NEXT_PUBLIC_PROXY_URL: process.env.NEXT_PUBLIC_PROXY_URL,
  };
  beforeEach(() => {
    delete process.env.DUEL_PROXY_URL;
    delete process.env.NEXT_PUBLIC_PROXY_URL;
  });
  afterEach(() => {
    for (const [k, v] of Object.entries(saved)) {
      if (v === undefined) delete process.env[k];
      else process.env[k] = v;
    }
  });

  test("defaults", () => {
    assert.equal(getProxyUrl(), DEFAULT_PROXY_URL);
  });
  test("reads DUEL_PROXY_URL and strips one trailing slash", () => {
    process.env.DUEL_PROXY_URL = "https://example.com/v1/";
    assert.equal(getProxyUrl(), "https://example.com/v1");
  });
  test("trims whitespace", () => {
    process.env.DUEL_PROXY_URL = "  http://localhost:8080  ";
    assert.equal(getProxyUrl(), "http://localhost:8080");
  });
  test("falls back to NEXT_PUBLIC_PROXY_URL", () => {
    process.env.NEXT_PUBLIC_PROXY_URL = "https://next.example.com/v1";
    assert.equal(getProxyUrl(), "https://next.example.com/v1");
  });
  test("DUEL_PROXY_URL wins", () => {
    process.env.DUEL_PROXY_URL = "https://a.example.com";
    process.env.NEXT_PUBLIC_PROXY_URL = "https://b.example.com";
    assert.equal(getProxyUrl(), "https://a.example.com");
