describe("deepMerge", () => {
  test("merges nested objects", () => {
    assert.deepEqual(
      deepMerge({ a: { b: 1, c: 2 }, d: 3 }, { a: { c: 9, e: 4 } }),
      { a: { b: 1, c: 9, e: 4 }, d: 3 },
    );
  });
  test("replaces arrays and scalars", () => {
    assert.deepEqual(deepMerge({ a: [1, 2, 3] }, { a: [4] }), { a: [4] });
    assert.deepEqual(deepMerge({ a: { b: 1 } }, { a: 5 }), { a: 5 });
    assert.deepEqual(deepMerge({ a: 5 }, { a: { b: 1 } }), { a: { b: 1 } });
  });
  test("null patch values replace", () => {
    assert.deepEqual(deepMerge({ a: { b: 1 } }, { a: null }), { a: null });
  });
  test("does not mutate its inputs", () => {
    const base = { a: { b: 1 } };
    const patch = { a: { c: 2 } };
    const out = deepMerge(base, patch);
    assert.deepEqual(base, { a: { b: 1 } });
    assert.deepEqual(patch, { a: { c: 2 } });
    assert.deepEqual(out, { a: { b: 1, c: 2 } });
  });
  test("empty patch clones", () => {
    const base = { a: 1 };
    const out = deepMerge(base, {});
    assert.deepEqual(out, { a: 1 });
    assert.notEqual(out, base);
  });
});

describe("checkConnectivity", () => {
  const realFetch = globalThis.fetch;
  afterEach(() => {
    globalThis.fetch = realFetch;
  });

  test("rejects a malformed key without any request", async () => {
    let called = false;
    globalThis.fetch = (async () => {
      called = true;
      return new Response("", { status: 200 });
    }) as typeof fetch;
    const res = await checkConnectivity("bad");
    assert.equal(called, false);
    assert.deepEqual(res, {
      ok: false,
      status: "invalid_key",
      message: `Invalid API key format. Get a key at ${DASHBOARD_URL}`,
    });
  });

  test("ok on the first successful probe", async () => {
    const urls: string[] = [];
    globalThis.fetch = (async (url: string, init: RequestInit) => {
      urls.push(String(url));
      assert.equal(init.method, "GET");
