describe("checkConnectivity", () => {
  const P = "https://p.example/v1";
  const realFetch = globalThis.fetch;
  afterEach(() => {
    globalThis.fetch = realFetch;
  });

  test("rejects a malformed key without any request", async () => {
    let called = false;
    globalThis.fetch = (async () => {
      called = true;
      return new Response("", { status: 200 });
    }) as typeof fetch;
    const res = await checkConnectivity("bad", P);
    assert.equal(called, false);
    assert.deepEqual(res, {
      ok: false,
      status: "invalid_key",
      message: "Invalid API key format. Get a key at " + DASHBOARD_URL,
    });
  });

  test("ok on the first successful probe", async () => {
    const urls: string[] = [];
    globalThis.fetch = (async (url: string, init: RequestInit) => {
      urls.push(String(url));
      assert.equal(init.method, "GET");
      const h = init.headers as Record<string, string>;
      assert.equal(h.Authorization, "Bearer " + KEY);
      assert.equal(h["Content-Type"], "application/json");
      return new Response("{}", { status: 200 });
    }) as unknown as typeof fetch;
    const res = await checkConnectivity(KEY, P + "/");
    assert.deepEqual(urls, [P + "/models"]);
    assert.deepEqual(res, {
      ok: true,
      status: "ok",
      httpStatus: 200,
      message: "Duel API is reachable and accepted your key.",
    });
  });

  for (const code of [401, 403]) {
    test("unauthorized on " + code, async () => {
      globalThis.fetch = (async () => new Response("", { status: code })) as typeof fetch;
      const res = await checkConnectivity(KEY, P);
      assert.deepEqual(res, {
        ok: false,
        status: "unauthorized",
        httpStatus: code,
        message:
          "API rejected your key (" + code + "). Create or renew a key at " + DASHBOARD_URL,
      });
    });
  }

  test("falls through to later probes", async () => {
    const urls: string[] = [];
    globalThis.fetch = (async (url: string) => {
      urls.push(String(url));
      return new Response("", { status: urls.length === 1 ? 404 : 200 });
    }) as unknown as typeof fetch;
    const res = await checkConnectivity(KEY, P);
    assert.deepEqual(urls, [P + "/models", P + "/health"]);
    assert.equal(res.ok, true);
    assert.equal(res.status, "ok");
  });

  test("tries all three probes then reports unreachable", async () => {
    const seen: Array<[string, string | undefined]> = [];
    globalThis.fetch = (async (url: string, init: RequestInit) => {
      seen.push([String(url), init.method]);
      return new Response("", { status: 500 });
    }) as unknown as typeof fetch;
    const res = await checkConnectivity(KEY, P);
    assert.deepEqual(seen, [
      [P + "/models", "GET"],
      [P + "/health", "GET"],
      [P, "HEAD"],
    ]);
    assert.equal(res.ok, false);
    assert.equal(res.status, "unreachable");
    assert.equal(res.httpStatus, 500);
    assert.equal(res.message, "Could not reach Duel API at " + P + ": HTTP 500");
  });

  test("network errors never throw", async () => {
    globalThis.fetch = (async () => {
      throw new Error("boom");
    }) as typeof fetch;
    const res = await checkConnectivity(KEY, P);
    assert.equal(res.ok, false);
    assert.equal(res.status, "unreachable");
    assert.equal(res.httpStatus, undefined);
    assert.equal(res.message, "Could not reach Duel API at " + P + ": boom");
  });
});
